// Git merge driver for the generated owner-config files (#1258):
// docs/config/config.schema.json and docs/config/config.example.json.
//
// Two branches that each add a config field both rewrite these files, so a line
// merge conflicts. The files are generated by tools/config/schema.mjs from the
// config classes' [Attribute] declarations, so this driver merges the SOURCES
// the generator reads (the .c scripts under Scripts/Game and
// tools/config/schema-overrides.json) three ways, runs the generator on the
// result and writes the output. A source file both sides changed is line-merged
// by `git merge-file` and conflicts only on overlapping edits (resolve that file
// by hand, then `node tools/config/schema.mjs --write`).
// Pack manifests are read from the working tree (the side being merged into).
//
//   node tools/merge/regen-config-schema.mjs %O %A %B %P

import { spawnSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL } from "node:url";
import { resolveSides } from "./regen-generated.mjs";

const SCRIPTS_PREFIX = "addons/LifeFramework/Scripts/Game/";
const SERVICE_REL = `${SCRIPTS_PREFIX}Core/Config/LF_ConfigService.c`;
const OVERRIDES_REL = "tools/config/schema-overrides.json";
const OUTPUTS = { "config.schema.json": "schema", "config.example.json": "example" };

function git(args) {
  return spawnSync("git", args, { windowsHide: true, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
}

export function configOutputKind(pathname) {
  const name = String(pathname ?? "").replace(/\\/g, "/").split("/").pop();
  return OUTPUTS[name] ?? null;
}

const norm = (text) => (text == null ? null : text.replace(/\r\n/g, "\n"));

/** Line merge of one text through `git merge-file -p`: { ok, text }; ok is false on overlapping edits. */
export function mergeText(base, ours, theirs) {
  const dir = mkdtempSync(join(tmpdir(), "lf-cfg-merge-"));
  try {
    const [o, b, t] = ["ours", "base", "theirs"].map((n) => join(dir, n));
    writeFileSync(o, norm(ours));
    writeFileSync(b, norm(base));
    writeFileSync(t, norm(theirs));
    const r = git(["merge-file", "-p", o, b, t]);
    return { ok: r.status === 0, text: r.stdout };
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
}

/** Three-way pick of one file: { ok, text } (text null when the winner deleted it). */
export function pickThree(base, ours, theirs, merge = mergeText) {
  if (norm(ours) === norm(theirs)) return { ok: true, text: ours };
  if (norm(ours) === norm(base)) return { ok: true, text: theirs };
  if (norm(theirs) === norm(base)) return { ok: true, text: ours };
  if (base == null || ours == null || theirs == null) return { ok: false };
  return merge(base, ours, theirs);
}

function showPath(rev, path) {
  const r = git(["-c", "core.autocrlf=false", "show", `${rev}:${path}`]);
  return r.status === 0 ? r.stdout : null;
}

function changedPaths(from, to) {
  const r = git(["diff", "--name-only", from, to, "--", SCRIPTS_PREFIX, OVERRIDES_REL]);
  if (r.status !== 0) return [];
  return r.stdout.split("\n").map((l) => l.trim()).filter((p) => p && (p.endsWith(".c") || p === OVERRIDES_REL));
}

/**
 * Merge the generator's sources three ways. `workFiles` are { path (repo-relative), text } from the
 * working tree. Returns { ok, files, overridesText } or { ok: false, error }.
 */
export function mergeSources(sides, workFiles, workOverrides, read = showPath, changed = changedPaths) {
  const touched = new Set([...changed(sides.base, sides.ours), ...changed(sides.base, sides.theirs)]);
  const byPath = new Map(workFiles.map((f) => [f.path, f.text]));
  let overridesText = workOverrides;
  for (const path of touched) {
    const picked = pickThree(read(sides.base, path), read(sides.ours, path), read(sides.theirs, path));
    if (!picked.ok) return { ok: false, error: `lf-regen-config: ${path} changed on both sides; resolve it, then node tools/config/schema.mjs --write` };
    if (path === OVERRIDES_REL) overridesText = picked.text ?? "{}";
    else if (picked.text == null) byPath.delete(path);
    else byPath.set(path, picked.text);
  }
  return { ok: true, files: [...byPath].map(([path, text]) => ({ path, text })), overridesText };
}

async function runDriver() {
  const oursPath = process.argv[3];
  const kind = configOutputKind(process.argv[5]);
  if (!oursPath || !kind) {
    console.error("lf-regen-config: expected docs/config/config.schema.json or config.example.json");
    process.exit(1);
  }
  const sides = resolveSides();
  if (!sides) {
    console.error("lf-regen-config: cannot identify the merge sides");
    process.exit(1);
  }
  const root = git(["rev-parse", "--show-toplevel"]).stdout.trim() || process.cwd();
  const gen = await import(pathToFileURL(join(root, "tools", "config", "schema.mjs")).href);
  const packs = await import(pathToFileURL(join(root, "tools", "config", "pack-sections.mjs")).href);
  const workFiles = gen.readScripts(join(root, ...SCRIPTS_PREFIX.split("/")))
    .map((f) => ({ path: f.path.slice(root.length + 1).replace(/\\/g, "/"), text: f.text }));
  const overridesFile = join(root, ...OVERRIDES_REL.split("/"));
  const workOverrides = existsSync(overridesFile) ? readFileSync(overridesFile, "utf8") : "{}";
  const merged = mergeSources(sides, workFiles, workOverrides);
  if (!merged.ok) {
    console.error(merged.error);
    process.exit(1);
  }
  const serviceText = merged.files.find((f) => f.path === SERVICE_REL)?.text ?? "";
  let out;
  try {
    const coreKeys = gen.coreKeysOf(merged.files);
    const loaded = packs.loadPackSections(join(root, "addons"), coreKeys);
    out = gen.generate(merged.files, serviceText, JSON.parse(merged.overridesText), loaded);
  } catch (err) {
    console.error(`lf-regen-config: the generator failed on the merged sources: ${err.message}`);
    process.exit(1);
  }
  writeFileSync(oursPath, gen.render(out[kind]));
}

const invoked = process.argv[1] && process.argv[1].replace(/\\/g, "/").endsWith("regen-config-schema.mjs");
if (invoked) await runDriver();
